arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: GetEnvironmentVariable returns null for empty
        // values on Unix. Use string.IsNullOrEmpty to detect "not set" only when
        // you don't need to distinguish empty from missing, or call the native API.
        // Here we need to distinguish, so we check via /proc/self/environ.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        bool exists = EnvironmentVariableExists("MY_FLAG");
        if (!exists)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    // .NET 9: empty env vars return null on Unix, same as unset.
    // To distinguish "explicitly empty" from "not set", check the environment block.
    private static bool EnvironmentVariableExists(string name)
    {
        var envVars = Environment.GetEnvironmentVariables();
        return envVars.Contains(name);
    }
}

